CREATE TABLE documents (kind TEXT NOT NULL, key TEXT NOT NULL, version INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (kind, key)) STRICT;
CREATE TABLE parts (kind TEXT NOT NULL, key TEXT NOT NULL, part TEXT NOT NULL, id TEXT NOT NULL, ord INTEGER NOT NULL, value TEXT NOT NULL, at INTEGER, grp TEXT, flag INTEGER, PRIMARY KEY (kind, key, part, id)) STRICT;
CREATE TABLE store_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE INDEX parts_at ON parts (kind, key, part, at) WHERE at IS NOT NULL;
CREATE INDEX parts_grp ON parts (kind, key, part, grp) WHERE grp IS NOT NULL;
CREATE INDEX parts_open ON parts (kind, key, part) WHERE at IS NULL;
CREATE INDEX parts_order ON parts (kind, key, part, ord);
